func (r *compilerRunner604) OpenChecks(ctx context.Context, q DependencyRequest) (RepositoryCheckEnvironment, error) {
	got, err := r.repositoryRunner582.OpenChecks(ctx, q)
	if got == nil || err != nil {
		return got, err
